import { PlaneGeometry, MeshBasicNodeMaterial, Mesh, Group } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  // Create group for future extensibility (children, etc.)
  const group = new Group();

  // Load texture from config.assets.imageUrl
  const texture = ctx.textureLoader.load(config.assets.imageUrl);

  // Determine material type based on effects description: static composition, no lighting
  const material = new MeshBasicNodeMaterial({ map: texture });

  // Geometry matching atlas source rect (0,0,512,320) - use custom size
  const geometry = new PlaneGeometry(512, 320); // units in scene space (scaling handles final size)
  const mesh = new Mesh(geometry, material);
  mesh.name = 'FeaturesCard3';

  // Apply scene placement from config.scenePosition
  if (config.scenePosition) {
    const { position, rotation, scale } = config.scenePosition;
    if (position) {
      if (Array.isArray(position)) {
        mesh.position.set(position[0], position[1], position[2]);
      } else {
        mesh.position.copy(position);
      }
    }
    if (rotation) {
      if (Array.isArray(rotation)) {
        mesh.rotation.set(rotation[0], rotation[1], rotation[2]);
      } else {
        mesh.rotation.copy(rotation);
      }
    }
    if (scale) {
      if (typeof scale === 'number') {
        mesh.scale.set(scale, scale, scale);
      } else if (Array.isArray(scale)) {
        mesh.scale.set(scale[0], scale[1], scale[2]);
      } else {
        mesh.scale.copy(scale);
      }
    }
  }

  group.add(mesh);

  // No cinematic primitives to apply (empty array)
  // If config.cinematicPrimitives were present, we would iterate and call ctx.primitives[name](...)

  // No text content – skip font atlas usage

  // Set up userData.handlers (empty as no interactions)
  group.userData.handlers = {};

  // Cleanup: dispose resources and kill GSAP timelines
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
    // Kill any GSAP timelines associated with this node (none here)
    gsap.killTweensOf(group);
  };

  return group;
}
